package in.industrend.identity.auth;
import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/v1/admin") class InternalAdminController{private final AdminAuthService auth;private final String serviceToken;InternalAdminController(AdminAuthService auth,@Value("${services.internal-token}")String token){this.auth=auth;this.serviceToken=token;}@GetMapping("/validate")Map<String,Object>validate(@RequestHeader("X-Service-Token")String supplied,@RequestHeader(value="X-Admin-Session",required=false)String session){if(!serviceToken.equals(supplied))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return auth.validate(session);}}
